$liabilityFields = ['short_term_debt'=>'Short-term debt','accounts_payable'=>'Accounts payable','other_current_liabilities'=>'Other current liabilities','total_current_liabilities'=>'Total current liabilities','long_term_debt'=>'Long-term debt','other_non_current_liabilities'=>'Other non-current liabilities','total_non_current_liabilities'=>'Total non-current liabilities','equity'=>'Equity','total_liabilities_and_equity'=>'Total liabilities and equity'];
$incomeFields = ['revenue'=>'Revenue','cost_of_goods_sold'=>'Cost of goods sold','gross_profit'=>'Gross profit','operating_expenses'=>'Operating expenses','ebitda'=>'EBITDA','depreciation_amortization'=>'Depreciation and amortization','ebit'=>'EBIT','interest_expense'=>'Interest expense','profit_before_tax'=>'Profit before tax','tax_expense'=>'Tax expense','net_profit'=>'Net profit'];
$calculatedBalanceFields = ['total_current_assets','total_non_current_assets','total_assets','total_current_liabilities','total_non_current_liabilities','total_liabilities_and_equity'];
$calculatedIncomeFields = ['gross_profit','ebitda','ebit','profit_before_tax','net_profit'];
if ($id && $pdo instanceof PDO) {
    $s = $pdo->prepare('SELECT fp.*, ca.application_number, ca.requested_amount, ca.currency, ca.status, ca.client_id, ca.interest_rate, ca.annual_debt_service_amount, c.client_name, c.idno FROM financial_periods fp INNER JOIN credit_applications ca ON ca.id = fp.application_id INNER JOIN clients c ON c.id = ca.client_id WHERE fp.id = ? AND fp.deleted_at IS NULL'); $s->execute([$id]); $period = $s->fetch();
    if ($period) { $s = $pdo->prepare('SELECT * FROM financial_balance_sheet WHERE financial_period_id = ?'); $s->execute([$id]); $balance = $s->fetch(); $s = $pdo->prepare('SELECT * FROM financial_income_statement WHERE financial_period_id = ?'); $s->execute([$id]); $income = $s->fetch(); $s = $pdo->prepare('SELECT * FROM financial_ratios WHERE financial_period_id = ? LIMIT 1'); $s->execute([$id]); $ratio = $s->fetch(); }
}
