if (!$period) { render_error_page('Financial period not found', 'The requested financial period does not exist or was deleted.', url('financials/index.php'), 'Back to financial statements'); require_once dirname(__DIR__) . '/footer.php'; exit; }
$rawBalance = $balance;
$balance = $balance ? calculate_balance_sheet_totals($balance) : null;
$income = $income ? calculate_income_statement_totals($income) : null;
$balanceDiff = $balance ? balance_difference($balance['total_assets'], $balance['total_liabilities_and_equity']) : 0.0;
$hasOldZeroTotals = $rawBalance && abs(decimal_value($rawBalance['total_assets'] ?? 0)) <= 0.01 && abs(decimal_value($rawBalance['total_liabilities_and_equity'] ?? 0)) <= 0.01 && has_nonzero_balance_base_values($rawBalance);
$isBalanced = $balance && abs($balanceDiff) <= 0.01;
$incomeIssues = $income ? check_income_statement_consistency($income) : [];
