    <div class="col-lg-6"><div class="card border-0 shadow-sm h-100"><div class="card-body p-4"><h2 class="h5 mb-3">Period information</h2><div class="row g-3"><?php foreach (['Period label'=>$period['period_label'],'Period type'=>$period['period_type'],'Period end date'=>format_date($period['period_end_date']),'Is audited'=>$period['is_audited'] ? 'Yes' : 'No','Data source'=>$period['data_source'],'Notes'=>$period['notes']] as $label=>$value): ?><div class="col-md-6"><div class="text-secondary small"><?= e($label) ?></div><div class="fw-semibold"><?= e($value ?: '-') ?></div></div><?php endforeach; ?></div></div></div></div>
