<div class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><div class="d-flex flex-column flex-lg-row justify-content-between gap-3 mb-3"><div><h2 class="h5 mb-1">Financial ratios</h2><p class="text-secondary small mb-0">Analytical indicators calculated from the entered balance sheet and income statement. For MVP, DSCR is calculated as EBITDA divided by the estimated annual debt service amount for the requested loan.</p></div><div class="d-flex gap-2 flex-wrap"><form method="post" action="<?= e(url('ratios/calculate.php')) ?>"><input type="hidden" name="financial_period_id" value="<?= e($period['id']) ?>"><button class="btn btn-primary" type="submit"><?= e($ratio ? 'Recalculate ratios' : 'Calculate ratios') ?></button></form><?php if ($ratio): ?><a class="btn btn-outline-primary" href="<?= e(url('ratios/view.php?financial_period_id=' . $period['id'])) ?>">Open detailed ratios</a><?php endif; ?></div></div><?php if (!$ratio): ?><div class="alert alert-warning mb-0">Financial ratios have not been calculated yet.</div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Ratio</th><th>Value</th><th>Interpretation</th></tr></thead><tbody><?php foreach (ratio_definitions() as $group): ?><tr class="table-secondary"><th colspan="3"><?= e($group['label']) ?></th></tr><?php foreach ($group['ratios'] as $key => $definition): ?><tr><td><?= e($definition['label']) ?></td><td><?= e(format_ratio($ratio[$key] ?? null, $definition['percent'])) ?></td><td><?= e(interpret_ratio($key, $ratio[$key] ?? null, ['equity' => $balance['equity'] ?? null])) ?></td></tr><?php endforeach; ?><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
